import {properties,sources,csv} from './model.mjs';
import {stages,channels,prospect,stageName,pipelineRecords,interactionHistory,contactStats,addInteraction,scheduleTour} from './prospects.mjs';

export function createLeasingWorkspace(api){
 const {esc,btn,chip,heading,panel,metric,icon,money,pName,sName,filters,getState,render,navigate,persist,toast}=api;
 let search='',source='all',page=0,recordTab='timeline',channel='all',direction='all',composeChannel='Email',composeDirection='outbound',returnRoute='pipeline/all';
 const s=()=>getState();
 const dt=value=>new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(value));
 const field=(label,value)=>`<div><dt>${label}</dt><dd>${esc(value??'Not recorded')}</dd></div>`;
 const details=items=>`<dl class="record-fields">${items.map(([k,v])=>field(k,v)).join('')}</dl>`;
 const stageButton=(id,label,value,property)=>`<button type="button" class="stage-card" data-action="drill-stage" data-stage="${id}" ${property?`data-property="${property}"`:''}><span>${label}</span><strong>${value}</strong><small>View records ${icon('arrow',13)}</small></button>`;
 function stageCards(m,property){return `<div class="stage-grid">${stages.map(([id,label])=>stageButton(id,label,id==='all'?m.leads.length:id==='leased'?m.leases:m[id],property)).join('')}</div>`;}
 function list(stage='all',communications=false){if(!stages.some(([x])=>x===stage))stage='all';let list=pipelineRecords(filters,s(),{stage,search,source});if(communications)list.sort((a,b)=>(contactStats(b.id,s()).last?.at||'').localeCompare(contactStats(a.id,s()).last?.at||''));page=Math.min(page,Math.max(0,Math.ceil(list.length/12)-1));
 const toolbar=`<div class="record-toolbar"><div class="field"><label for="pipeline-search">Search prospects</label><input id="pipeline-search" placeholder="Name, ID, email, phone or property" value="${esc(search)}"></div><div class="field"><label for="pipeline-source">Original source</label><select id="pipeline-source"><option value="all">All sources</option>${sources.map(x=>`<option value="${x.id}" ${source===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div>${btn(icon('download')+' Export records','pipeline-export',`data-stage="${stage}"`,'secondary')}</div>`;
 const cards=list.slice(page*12,page*12+12).map(l=>{const stats=contactStats(l.id,s());return `<article class="prospect-card"><div class="prospect-card-top"><span class="avatar teal">${esc(l.name.split(' ').map(x=>x[0]).join(''))}</span><div><button class="link prospect-name" data-action="open-prospect" data-id="${l.id}">${esc(l.name)}</button><small>${l.contactId} · ${l.id}</small></div>${chip(stageName(l),l.leased?'good':'info')}</div><div class="prospect-summary"><strong>${pName(l.property)}</strong><small>${sName(l.source)} · Enquired ${l.created}</small></div><div class="contact-counts"><span><strong>${stats.total}</strong> interactions</span><span><strong>${stats.inbound}</strong> inbound</span><span><strong>${stats.outbound}</strong> outbound</span></div><p class="last-message">${communications&&stats.last?esc(stats.last.subject):`${l.bedrooms} bedrooms · ${money(l.budget)} budget · ${esc(l.owner)}`}</p><div class="prospect-card-bottom"><small>${stats.last?dt(stats.last.at):'No activity'}</small>${btn('Open record '+icon('arrow',14),'open-prospect',`data-id="${l.id}"`,'secondary small')}</div></article>`;}).join('');
 return heading(communications?'Every conversation. One shared history.':'From portfolio to person.',communications?'Email, SMS, calls, chat and visits stay linked to the same prospect.':'Open any record to inspect the full journey, contact history and leasing details.',btn('Portfolio overview','navigate','data-route="portfolio"','secondary'),communications?'Communications':'Leasing workspace')+`<div class="insight">${icon('info')}<span>${communications?'Demo communications are saved in this browser. No messages are delivered and no live inboxes or phone lines are connected.':'Counts are cumulative milestones for the selected enquiry cohort. A signed lease also appears in applications and completed tours.'}</span></div>`+(!communications?`<nav class="tabs" aria-label="Leasing stages">${stages.map(([id,label])=>btn(label,'drill-stage',`data-stage="${id}" ${stage===id?'aria-current="page"':''}`,`stage-tab ${stage===id?'selected':'secondary'}`)).join('')}</nav>`:'')+panel(`${communications?'Conversations':stages.find(([x])=>x===stage)[1]} · ${list.length} prospects`,'Your property, city, management company and cohort filters remain active.',toolbar+(cards?`<div class="prospect-grid">${cards}</div>`:`<div class="empty"><h3>No matching prospects</h3><p>Change the search or filters to see more records.</p>${btn('Reset record search','pipeline-reset','','secondary')}</div>`)+`<div class="pagination"><span>${list.length?page*12+1:0}–${Math.min(list.length,(page+1)*12)} of ${list.length}</span><div>${btn('Previous','pipeline-page',`data-delta="-1" ${page===0?'disabled':''}`,'secondary small')}${btn('Next','pipeline-page',`data-delta="1" ${(page+1)*12>=list.length?'disabled':''}`,'secondary small')}</div></div>`);
 }
 function timeline(l){const events=interactionHistory(l.id,s()).filter(x=>(channel==='all'||x.channel===channel)&&(direction==='all'||x.direction===direction));return `<div class="record-toolbar compact"><label>Channel <select id="timeline-channel"><option value="all">All channels</option>${channels.map(x=>`<option ${x===channel?'selected':''}>${x}</option>`).join('')}</select></label><label>Direction <select id="timeline-direction">${[['all','All directions'],['inbound','Inbound'],['outbound','Outbound'],['internal','Internal notes']].map(([id,label])=>`<option value="${id}" ${id===direction?'selected':''}>${label}</option>`).join('')}</select></label><small>${events.length} records</small>${btn('Export history','history-export',`data-id="${l.id}"`,'secondary small')}</div><p class="footnote">Newest first · timestamps shown in your local timezone · notes and drafts are excluded from interaction counts.</p><ol class="conversation-timeline">${events.map(x=>`<li class="interaction ${x.direction}"><div class="interaction-head"><span class="channel-icon">${icon(x.channel==='Phone'?'people':x.channel==='Note'?'tasks':'message',16)}</span><strong>${esc(x.channel)} · ${x.direction==='inbound'?'Incoming':x.direction==='outbound'?'Outgoing':'Internal'}</strong><time datetime="${x.at}">${dt(x.at)}</time></div><h3>${esc(x.subject)}</h3><p>${esc(x.body)}</p><div class="interaction-footer"><small>${esc(x.agent)}${x.duration?` · ${Math.round(x.duration/60)} min`:''}${x.outcome?' · '+esc(x.outcome):''}</small>${chip(x.status)}</div><small class="interaction-id">${esc(x.id)}</small></li>`).join('')||'<li class="empty">No interactions match these filters.</li>'}</ol>`;}
 function composer(l){const log=['Phone','Visit','Note'].includes(composeChannel),internal=composeChannel==='Note';return `<form id="communication-form" data-id="${l.id}"><div class="record-toolbar compact"><div class="field"><label for="compose-channel">Channel</label><select id="compose-channel" name="channel">${channels.map(x=>`<option ${x===composeChannel?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="compose-direction">Direction</label><select id="compose-direction" name="direction">${(internal?[['internal','Internal note']]:[['outbound','Outgoing'],['inbound','Incoming demo']]).map(([id,label])=>`<option value="${id}" ${composeDirection===id?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="recipient-strip"><strong>${esc(l.name)}</strong><span>${esc(composeChannel==='Email'?l.email:l.phone)} · Fictional contact</span></div><div class="field"><label for="message-subject">${log?'Interaction title':'Subject / topic'}</label><input id="message-subject" name="subject" maxlength="140" required placeholder="${log?'Follow-up call about availability':'Follow-up on your enquiry'}"></div><div class="field"><label for="message-body">${log?'Notes / conversation summary':'Message'}</label><textarea id="message-body" name="body" maxlength="5000" required placeholder="${log?'Record the discussion, outcome and next step…':'Write your message…'}"></textarea></div>${['Phone','Visit'].includes(composeChannel)?`<div class="record-toolbar compact"><div class="field"><label for="call-duration">Duration (minutes)</label><input id="call-duration" name="minutes" type="number" min="0" max="1440" value="5"></div><div class="field"><label for="call-outcome">Outcome</label><select id="call-outcome" name="outcome">${['Connected','Voicemail','No answer','Completed','Follow-up required'].map(x=>`<option>${x}</option>`).join('')}</select></div></div>`:''}<div class="notice">${composeChannel==='Phone'?'Call logging only. Calling, audio recording and transcription need a telephony provider.':composeDirection==='inbound'?'Simulate an incoming message to demonstrate the shared history. Live inbox capture needs a provider connection.':'Demo only. This records the interaction locally; nothing is sent to the prospect.'}</div><p id="communication-error" class="form-error" role="alert"></p><button class="btn" type="submit">${log?'Save interaction':composeDirection==='inbound'?'Record incoming demo':'Send demo message'}</button></form>`;}
 function recordDetails(l){return panel('Enquiry & contact','A single contact ID links every channel and milestone.',details([['Contact ID',l.contactId],['Enquiry ID',l.id],['Email',l.email],['Phone',l.phone],['Created',l.created],['Preferred channel',l.preferredChannel],['Assigned owner',l.owner],['Original source',sName(l.source)],['Campaign',l.campaign],['UTM source',l.utmSource],['UTM medium',l.utmMedium],['Bedrooms',l.bedrooms],['Budget / month',money(l.budget)],['Preferred move-in',l.moveIn],['Property',pName(l.property)],['Contact consent','Demo placeholder · verify before live outreach']]))+panel('Record provenance','Fictional demonstration data.',`<p class="muted">Prospects are linked by a stable contact ID, not by matching names. Original-source attribution remains separate from the multi-channel interaction history. Live identity matching, consent records and provider delivery receipts require integrations.</p>`);}
 function tourPanel(l){return panel('Tour details','Appointments remain linked to the original enquiry.',l.tour?details([['Tour ID','TOUR-'+l.id],['Status',l.tour.status],['Date',l.tour.date],['Time',l.tour.time+' · property local time'],['Tour type',l.tour.type],['Leasing host',l.tour.host],['Unit / home',l.tour.unit],['Notes',l.tour.notes]])+`<p class="footnote">The original demo snapshot is through Nov 13, 2026. A scheduled tour does not imply it was completed.</p>`:`<form id="tour-form" data-id="${l.id}"><div class="empty compact-empty"><h3>No tour scheduled</h3><p>Book a sample appointment and record its confirmation in the contact history.</p></div><div class="record-toolbar"><div class="field"><label for="tour-date">Date</label><input id="tour-date" name="date" type="date" min="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label for="tour-time">Time (property local)</label><input id="tour-time" name="time" type="time" value="14:00" required></div><div class="field"><label for="tour-type">Tour type</label><select id="tour-type" name="type"><option>In person</option><option>Virtual</option></select></div></div><div class="field"><label for="tour-notes">Appointment notes</label><textarea id="tour-notes" name="notes" maxlength="1000" placeholder="Meeting point or accessibility requests for the sample appointment"></textarea></div><p class="form-error" id="tour-error" role="alert"></p><button type="submit" class="btn">Book demo tour</button><p class="footnote">Updates the scheduled-tour count and logs a demo confirmation. No external calendar invitation is sent.</p></form>`);}
 function applicationPanel(l){return panel('Application details','Application status is shown independently of the tour.',l.application?details([['Application ID',l.application.id],['Received',l.application.received],['Status',l.application.status],['Applicants',l.application.applicants],['Requested unit',l.unit],['Preferred move-in',l.moveIn]])+`<h3>Document checklist</h3><div class="document-list">${l.application.documents.map(([name,status])=>`<div class="row"><span>${name}</span>${chip(status)}</div>`).join('')}</div><p class="notice">${l.application.note}</p>`:`<div class="empty"><h3>No application received</h3><p>This prospect has not reached the application milestone.</p>${btn('Open conversations','record-tab','data-tab="compose"','secondary')}</div>`);}
 function leasePanel(l){return panel('Lease details','Signed lease metadata and move-in handoff.',l.lease?details([['Lease ID',l.lease.id],['Status',l.lease.status],['Signed',l.lease.signed],['Lease start',l.lease.start],['Lease end',l.lease.end],['Monthly rent',money(l.lease.rent)],['Term',l.lease.term],['Unit / home',l.unit],['Property',pName(l.property)],['Days from enquiry',l.days],['Linked application',l.application.id],['Document',l.lease.document]]):`<div class="empty"><h3>No signed lease</h3><p>A lease record will appear here when the signed-lease milestone is recorded.</p>${btn('View application','record-tab','data-tab="application"','secondary')}</div>`);}
 function detail(id){const l=prospect(id,s());if(!l)return heading('Prospect not found','This record is not in the demo dataset.',btn('Back to enquiries','navigate','data-route="pipeline/all"'));const stats=contactStats(id,s());const tabs=[['timeline','Interaction history'],['details','Contact & enquiry'],['tour','Tour'],['application','Application'],['lease','Lease'],['compose','New interaction']];return `<div class="record-breadcrumb">${btn('← Back to records','navigate',`data-route="${returnRoute}"`,'ghost')}<span>${pName(l.property)} / ${l.contactId}</span></div>`+heading(esc(l.name),`${l.contactId} · ${l.id} · Fictional prospect`,chip(stageName(l),l.leased?'good':'info'),'Prospect 360')+`<div class="metrics record-metrics">${metric('Total interactions',stats.total,'All recorded contact channels','message')}${metric('Inbound contacts',stats.inbound,'Times the prospect got in touch','people')}${metric('Outbound follow-ups',stats.outbound,'Leasing team interactions','arrow')}${metric('Channels used',stats.channels.length,stats.channels.join(' · '),'globe')}</div><div class="prospect-layout"><aside class="panel contact-panel"><div class="profile-avatar">${esc(l.name.split(' ').map(x=>x[0]).join(''))}</div><h2>${esc(l.name)}</h2><p>${pName(l.property)}</p>${details([['Email',l.email],['Phone',l.phone],['Original source',sName(l.source)],['Preferred channel',l.preferredChannel]])}<div class="field"><label for="prospect-owner">Leasing owner</label><select id="prospect-owner" data-id="${l.id}">${properties.map(p=>`<option ${p.owner===l.owner?'selected':''}>${p.owner}</option>`).join('')}</select></div>${btn(icon('message')+' New interaction','record-tab','data-tab="compose"')}${btn('Create follow-up task','task',`data-key="lead-${l.id}" data-property="${l.property}" data-title="Follow up with ${esc(l.name)}"`,'secondary')}<div class="milestone-list">${[['Enquiry received',true],['Tour scheduled',l.scheduled],['Tour completed',l.toured],['Application received',l.applied],['Lease signed',l.leased]].map(([name,done])=>`<div class="${done?'reached':''}"><span>${done?'✓':'○'}</span>${name}</div>`).join('')}</div><p class="footnote">Same contact across every interaction. Names are never used to merge people automatically.</p></aside><div class="record-main"><nav class="tabs record-tabs" aria-label="Prospect detail views">${tabs.map(([id,label])=>btn(label,'record-tab',`data-tab="${id}" ${recordTab===id?'aria-current="page"':''}`,recordTab===id?'selected':'secondary')).join('')}</nav>${recordTab==='details'?recordDetails(l):recordTab==='tour'?tourPanel(l):recordTab==='application'?applicationPanel(l):recordTab==='lease'?leasePanel(l):recordTab==='compose'?panel('Record the next conversation','One workspace for inbound and outbound activity.',composer(l)):panel('Complete interaction history','Every touchpoint, with direction, owner and timestamp.',timeline(l))}</div></div>`;}
 function download(rows,name){const url=URL.createObjectURL(new Blob(['\uFEFF'+csv(rows)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exported.');}
 function exportList(stage){const ls=pipelineRecords(filters,s(),{stage,search,source});download([['Contact ID','Enquiry ID','Name','Property','Email','Phone','Original source','Stage','Owner','Created','Tour date','Application ID','Lease ID','Total interactions','Inbound','Outbound'],...ls.map(l=>{const c=contactStats(l.id,s());return [l.contactId,l.id,l.name,pName(l.property),l.email,l.phone,sName(l.source),stageName(l),l.owner,l.created,l.tour?.date,l.application?.id,l.lease?.id,c.total,c.inbound,c.outbound];})],`MF-Hub-${stage}-records`);}
 return {stageCards,list,detail,exportList,
  open(id){recordTab='timeline';channel=direction='all';if(!location.hash.startsWith('#prospect/'))returnRoute=location.hash.slice(1)||'pipeline/all';navigate('prospect/'+id);},
  action(b){const {action,id}=b.dataset;if(action==='drill-stage'){if(b.dataset.property)Object.assign(filters,{property:b.dataset.property,pmc:'all',city:'all'});search='';source='all';page=0;navigate('pipeline/'+(b.dataset.stage||'all'));}else if(action==='open-prospect')this.open(id);else if(action==='pipeline-page'){page+=Number(b.dataset.delta);render();}else if(action==='pipeline-reset'){search='';source='all';page=0;render();}else if(action==='record-tab'){recordTab=b.dataset.tab;render();document.querySelector('.record-main')?.scrollIntoView({block:'start',behavior:'smooth'});}else if(action==='pipeline-export')exportList(b.dataset.stage||'all');else if(action==='history-export'){const events=interactionHistory(id,s()).filter(x=>(channel==='all'||x.channel===channel)&&(direction==='all'||x.direction===direction));download([['Interaction ID','Contact ID','Date UTC','Direction','Channel','Subject','Body','Owner','Status','Duration seconds','Outcome'],...events.map(x=>[x.id,x.contactId,x.at,x.direction,x.channel,x.subject,x.body,x.agent,x.status,x.duration,x.outcome])],`MF-Hub-${id}-interactions`);}else return false;return true;},
  change(el){const form=document.getElementById('communication-form');const draft=form?Object.fromEntries(new FormData(form)):null;if(el.id==='pipeline-source'){source=el.value;page=0;}else if(el.id==='timeline-channel')channel=el.value;else if(el.id==='timeline-direction')direction=el.value;else if(el.id==='compose-channel'){composeChannel=el.value;composeDirection=el.value==='Note'?'internal':'outbound';}else if(el.id==='compose-direction')composeDirection=el.value;else if(el.id==='prospect-owner'){s().prospectOwners[el.dataset.id]=el.value;persist();toast('Leasing owner updated.');}else return false;render();if(draft&&document.getElementById('communication-form'))for(const name of ['subject','body','minutes','outcome']){const field=document.querySelector(`#communication-form [name="${name}"]`);if(field&&draft[name]!==undefined)field.value=draft[name];}return true;},
  input(el){if(el.id!=='pipeline-search')return false;search=el.value;page=0;const pos=el.selectionStart;render();const input=document.getElementById('pipeline-search');input.focus();input.setSelectionRange(pos,pos);return true;},
  submit(event){const form=event.target;if(!['communication-form','tour-form'].includes(form.id))return false;event.preventDefault();const values=Object.fromEntries(new FormData(form));try{if(form.id==='communication-form'){addInteraction(s(),{...values,leadId:form.dataset.id,duration:Number(values.minutes||0)*60});persist();recordTab='timeline';channel=direction='all';render();toast('Demo interaction recorded. Contact totals updated.');}else{scheduleTour(s(),form.dataset.id,values);persist();render();toast('Demo tour booked and confirmation recorded.');}}catch(error){document.getElementById(form.id==='communication-form'?'communication-error':'tour-error').textContent=error.message;}return true;}
 };
}
